import math
    import random
    import time

    LANGUAGE_WRAPPER = 'On a {n}×{n} chessboard, place m standard 1×2 dominoes so that every placed domino is jammed: no domino can slide along its own axis when all other dominoes remain fixed. Among all such jammed configurations on this {n}×{n} board (with at least one domino placed), determine the minimal possible value of m.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Pick an odd n >= 7 to avoid small degenerate cases
candidates = [x for x in range(7, 31) if x % 2 == 1]
n = rng.choice(candidates)
return {'n': n}

    def verifier(assign):
# Validate input
if 'n' not in assign:
    # Missing slot
    return (False, None)
n = assign['n']
if not isinstance(n, int):
    # Wrong type
    return (False, None)
if n < 7 or n % 2 != 1:
    # Enforce odd n >= 7 to avoid trivial/degenerate instances
    return (False, None)
# For odd n >= 7, the minimal number m of dominoes in a jammed configuration
# (no domino can slide along its axis) is given by:
# m_min = (n^2 - 5)/2.
# This matches the known 7x7 case: (49 - 5)/2 = 22.
# We return it as an integer.
answer = (n * n - 5) // 2
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

